$find=$pdo->prepare('SELECT * FROM conversations_boutique WHERE visitor_token=?');$find->execute([$token]);$conversation=$find->fetch(PDO::FETCH_ASSOC);
if($_SERVER['REQUEST_METHOD']==='POST'){$payload=json_decode((string)file_get_contents('php://input'),true)?:[];if(!hash_equals((string)($_SESSION['public_chat_csrf']??''),(string)($payload['csrf']??''))){http_response_code(403);echo json_encode(['error'=>'Session expirée']);exit;}$message=trim((string)($payload['message']??''));if($message===''||mb_strlen($message)>1500){http_response_code(422);echo json_encode(['error'=>'Message invalide']);exit;}if(!$conversation){$pdo->prepare('INSERT INTO conversations_boutique(visitor_token,nom_visiteur,email_visiteur,produit_id) VALUES(?,?,?,?)')->execute([$token,trim((string)($payload['name']??''))?:null,filter_var($payload['email']??'',FILTER_VALIDATE_EMAIL)?:null,(int)($payload['product_id']??0)?:null]);$conversation=['id'=>(int)$pdo->lastInsertId()];}else{$pdo->prepare("UPDATE conversations_boutique SET statut='ouverte',updated_at=NOW(),nom_visiteur=COALESCE(NULLIF(?,''),nom_visiteur),email_visiteur=COALESCE(NULLIF(?,''),email_visiteur) WHERE id=?")->execute([trim((string)($payload['name']??'')),filter_var($payload['email']??'',FILTER_VALIDATE_EMAIL)?:'',(int)$conversation['id']]);}$pdo->prepare("INSERT INTO messages_boutique(conversation_id,expediteur,message) VALUES(?,'visiteur',?)")->execute([(int)$conversation['id'],$message]);echo json_encode(['success'=>true]);exit;}
if(!$conversation){echo json_encode(['messages'=>[]]);exit;}$pdo->prepare("UPDATE messages_boutique SET lu_at=NOW() WHERE conversation_id=? AND expediteur='utilisateur' AND lu_at IS NULL")->execute([(int)$conversation['id']]);$s=$pdo->prepare('SELECT id,expediteur,message,created_at FROM messages_boutique WHERE conversation_id=? ORDER BY id');$s->execute([(int)$conversation['id']]);echo json_encode(['messages'=>$s->fetchAll(PDO::FETCH_ASSOC)],JSON_UNESCAPED_UNICODE);
